css:
/* Scoped to the theme: picking another theme turns these off too. */
:root[data-theme="plugin:example.dusk-theme"] .page-header h1 { letter-spacing: -0.025em; }
:root[data-theme="plugin:example.dusk-theme"] .status-dot[data-tone="success"] {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--status-success) 22%, transparent);
}
